head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > ondatadragover]<br/>Drag 된 데이터가 GridView 영역을 이동할 때 발생합니다.",
    "validation" : [
        "dataDragDrop, dataDragDropSelf, dataDragDropOther, dataDragDropCell 속성 중 하나 이상 true 여야 이벤트가 발생합니다.",
        "Drag 가 시작된 GridView 에선 발생하지 않고 다른 GridView 를 Drag 데이터가 이동할 때 해당 GridView 에서 발생합니다.",
        "fromId : Drag 가 시작된 GridView 의 렌더링 ID 값이 전달됩니다.",
        "fromRowIndex : Drag 가 시작된 데이터의 Row 인덱스값이 전달됩니다.",
        "ondatadragover 이벤트는 GridView 데이터가 Drag 된 경우만 발생합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제 (2개 그리드 + 2개 dataList)
    if (typeof dlt_bind1 !== 'undefined') {
        $p.data.remove("dlt_bind1");
    }
    if (typeof dlt_bind2 !== 'undefined') {
        $p.data.remove("dlt_bind2");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    if (typeof target2 !== 'undefined') {
        target2.remove();
    }
    // 이전에 만든 flex wrapper 도 제거 (Target 재생성 시 중복 누적 방지)
    if (scwin.gridFlexWrap && scwin.gridFlexWrap.parentNode) {
        scwin.gridFlexWrap.parentNode.removeChild(scwin.gridFlexWrap);
    }

    // 안내 라벨 (가장 먼저 생성)
    //  - ondatadragover 는 Drag 가 시작된 그리드(target1)가 아니라, Drag 데이터가 지나가는 다른 그리드(target2)에서 발생
    //  - 사용자 액션(Drag)으로 발생 -> 절차/확인 안내
    $c.gcm.createLabel('label="[전제] 왼쪽=target1(Drag 소스), 오른쪽=target2(Drag-over 대상). 양쪽 dataDragDropOther=true.\n[절차] target1 의 Row 를 Drag 하여 target2 영역 위로 이동 -> target2 에서 ondatadragover 발생(fromId/fromRowIndex 출력).\n[확인] Drag 시작 그리드(target1)에선 미발생, 대상(target2)에서만 발생합니다."', '', 'label1');

    // 좌우 배치용 flex wrapper 와 좌/우 셀(원시 DOM div) 생성
    //  - 기본 케이스가 .tc_group_basic(원시 DOM)을 dynamicCreate parent 로 쓰므로 좌/우 셀도 원시 DOM div 로 생성
    //  - 각 셀을 createBasicGridView 의 cParent 로 넘겨 두 그리드를 양옆으로 배치
    let grpBasic = document.querySelector('.tc_group_basic');
    scwin.gridFlexWrap = document.createElement('div');
    scwin.gridFlexWrap.style.cssText = 'display:flex; gap:20px; align-items:flex-start;';
    let cellLeft = document.createElement('div');
    let cellRight = document.createElement('div');
    scwin.gridFlexWrap.appendChild(cellLeft);
    scwin.gridFlexWrap.appendChild(cellRight);
    grpBasic.appendChild(scwin.gridFlexWrap);

    // 양 그리드에 dataDragDropOther=true (교차 그리드 Drag&Drop 허용)
    //  - dataDragDrop/dataDragDropSelf/dataDragDropOther/dataDragDropCell 중 하나 이상 true 여야 ondatadragover 발생
    let properties1 = {
        dataList: "data:dlt_bind1",
        dataDragDropOther: "true"
    };
    let properties2 = {
        dataList: "data:dlt_bind2",
        dataDragDropOther: "true"
    };

    let cList1 = $c.gcm.createCList(properties1);
    let cList2 = $c.gcm.createCList(properties2);

    // ondatadragover 발생 횟수 카운터 초기화 (ondatadragover 는 mousemove 처럼 Drag-over 동안 연속 발생 -> 3회까지만 출력)
    scwin.overCnt = 0;

    // 이벤트 핸들러 부착
    //  - target2(Drag-over 대상) : ondatadragover (검증 대상)
    //  - target1(Drag 소스) : ondatadragstart (Drag 시작 시 ondatadragover 출력 카운터 초기화 -> 새 Drag 마다 다시 3회 출력)
    let eList1 = $c.gcm.createEList(["ondatadragstart"], "target1");
    let eList2 = $c.gcm.createEList(["ondatadragover"], "target2");

    // dataList 2개 생성 (각 그리드 바인딩)
    $c.gcm.createBasicDataList('', '', 'dlt_bind1');
    $c.gcm.createBasicDataList('', '', 'dlt_bind2');

    // target 2개 생성 (target1 : Drag 소스 = 왼쪽 / target2 : Drag-over 대상 = 오른쪽)
    //  - cParent 로 좌/우 셀(원시 DOM div)을 전달 -> getTestGroup 이 그대로 반환하여 해당 셀에 생성
    await $c.gcm.createBasicGridView(cList1, eList1, 'target1', cellLeft);
    await $c.gcm.createBasicGridView(cList2, eList2, 'target2', cellRight);
}



// ondatadragover : Drag 된 데이터가 (다른) GridView 영역을 이동할 때 해당 GridView(target2)에서 발생 (검증 대상)
//  - fromId       : Drag 가 시작된 GridView 의 렌더링 ID (= target1 의 렌더링 id)
//  - fromRowIndex : Drag 가 시작된 데이터의 Row 인덱스
scwin.target2_ondatadragover = function (fromId, fromRowIndex) {
    var bottom = wf_body_bottom.getObj("scwin");
    // ondatadragover 는 Drag-over 동안 연속 발생 -> mousemove 샘플처럼 3회까지만 출력 (이후 생략)
    if (scwin.overCnt < 3) {
        bottom.setReturnValue("ondatadragover fromId : " + fromId);
        bottom.setReturnValue("ondatadragover fromRowIndex : " + fromRowIndex);
        if (scwin.overCnt === 2) {
            bottom.setReturnValue("... (이후 ondatadragover 출력 생략)");
        }
    }
    scwin.overCnt += 1;
};



// ondatadragstart : Drag 시작 그리드(target1)에서 발생 -> ondatadragover 출력 카운터 초기화 (새 Drag 마다 다시 3회 출력)
scwin.target1_ondatadragstart = function (fromId, fromRowIndex) {
    scwin.overCnt = 0;
};
